using System;
using System.Linq;
using AICad.Contracts;
using AICad.Geometry;
using Newtonsoft.Json.Linq;
namespace AICad.Application;
public sealed class DraftingLibraryService(WorkspaceService workspace){
 public object Standards()=>workspace.Store.Ids("standards").Select(id=>workspace.Store.Read<LayerStandard>("standards",id)).ToList();
 public LayerStandard Standard(string id)=>workspace.Store.Read<LayerStandard>("standards",id);
 public LayerStandard PublishStandard(JObject p){var t=workspace.Template(p.Value<string>("templateId")??"");var standard=new LayerStandard{Id=p.Value<string>("id")??"",Name=p.Value<string>("name")??"",Version=p.Value<string>("version")??"",Layers=Json.Read<System.Collections.Generic.List<LayerAsset>>(Json.Write(t.Layers)),Roles=p["roles"]?.ToObject<System.Collections.Generic.Dictionary<string,string>>()??new()};Json.Name(standard.Id);if(string.IsNullOrWhiteSpace(standard.Name)||standard.Name.Length>120||standard.Roles.Count>20||standard.Roles.Any(r=>!standard.Layers.Any(l=>l.Name==r.Value)))throw new CadException("INVALID_STANDARD","Kiểm tra tên và layer theo vai trò.");Validation.Template(t);workspace.Store.Publish("standards",standard.Id,standard.Version,standard);return standard;}
 public TemplateProfile Catalog(JObject p){var t=Json.Read<TemplateProfile>(Json.Write(workspace.Template(p.Value<string>("templateId")??"")));var original=t.Blocks.SingleOrDefault(b=>b.Id==p.Value<string>("assetId"))??throw new CadException("MISSING_ASSET","Chọn block gốc.");var b=Json.Read<BlockAsset>(Json.Write(original));b.Id=p.Value<string>("id")??"";b.Usage=p["usage"]?.ToObject<BlockUsage>()??throw new CadException("INVALID_CATALOG","Thiếu cấu hình loại block.");if(b.NativeSource==null)throw new CadException("INVALID_CATALOG","Chọn block CAD gốc.");t.Blocks.RemoveAll(x=>x.Id==b.Id);t.Blocks.Add(b);t.Version=p.Value<string>("version")??"";workspace.ImportTemplate(t);return t;}
 public SkillDefinition SyncSource(string id){workspace.Catalog.Available("skills",id);var s=Json.Read<SkillDefinition>(Json.Write(workspace.Store.Skill(id)));if(s.Builder!="source"||s.Recipe==null)throw new CadException("SKILL_MISMATCH","Chọn Skill nguồn có bộ quy tắc.");var t=workspace.Template(s.TemplateId);workspace.Catalog.Available("templates",t.Id);var ready=t.Blocks.Where(b=>b.Usage?.Reviewed==true&&(b.Usage.WidthParameter==""||b.Usage.ConversionConfirmed)&&(!s.Recipe.Layers.TryGetValue(b.Usage.Role,out var layer)||layer==b.Usage.Layer)).Select(b=>b.Id).ToList();if(ready.Count==0)throw new CadException("CATALOG_REVIEW_REQUIRED","Chưa có loại block được duyệt. Mở Cấu hình block, kiểm tra và xuất bản ít nhất một loại trước.");s.Recipe.AllowedBlocks=ready;var v=new Version(s.Version);int patch=Math.Max(0,v.Build)+1;while(workspace.Store.Versions("skills",s.Id).Contains($"{v.Major}.{v.Minor}.{patch}"))patch++;s.Version=$"{v.Major}.{v.Minor}.{patch}";workspace.ImportSkill(s);return s;}
 public SkillDefinition Wizard(JObject p){var standard=Standard(p.Value<string>("standardId")??"");var t=workspace.Template(p.Value<string>("templateId")??"");var recipe=p["recipe"]?.ToObject<DraftingRecipe>()??new();recipe.StandardId=standard.Id;recipe.StandardVersion=standard.Version;recipe.Layers=standard.Roles;foreach(var layer in standard.Layers){var found=t.Layers.SingleOrDefault(l=>l.Name==layer.Name);if(found==null||Json.Hash(found)!=Json.Hash(layer))throw new CadException("STANDARD_MISMATCH","Template và bộ layer khác nhau: "+layer.Name);}var s=new SkillDefinition{Id=p.Value<string>("id")??"",Name=p.Value<string>("name")??"",Version=p.Value<string>("version")??"1.0.0",TemplateId=t.Id,Builder=p.Value<string>("builder")??"source",RequiredTools=Validation.Tools,RequiredInputs=p.Value<string>("builder")=="custom"?Array.Empty<string>():new[]{"sourceId","confirmGeometry"},Recipe=recipe};if(s.Builder!="source"&&s.Builder!="custom")throw new CadException("UNSUPPORTED_BUILDER","Chọn dựng ảnh/PDF hoặc chat CAD.");DraftingRules.Recipe(recipe,t);foreach(string id in recipe.AllowedBlocks){var b=t.Blocks.Single(x=>x.Id==id);if(b.Usage?.Reviewed!=true)throw new CadException("CATALOG_REVIEW_REQUIRED",id);}workspace.ImportSkill(s);return s;}
}
